import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {{ x: number, y: number, z: number }} position
 * @property {{ x: number, y: number, z: number }} rotation
 * @property {{ x: number, y: number, z: number }} scale
 * @property {Array<{ name: string, params: any }>} cinematicPrimitives
 * @property {string} imageUrl
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url: string) => THREE.Texture} textureLoader
 * @property {{ [key: string]: (obj: THREE.Object3D, params?: any) => void }} primitives
 * @property {{ emit?: (event: string) => void }} [emit] - optional event emitter
 */

/**
 * Create a textured plane node with hover lift and click emit behavior,
 * applying requested cinematic primitives.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Geometry – unit plane, size will be driven by scaling if needed
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Load texture (synchronous via ctx.textureLoader)
  const texture = ctx.textureLoader(config.imageUrl);
  texture.needsUpdate = true;
  texture.minFilter = THREE.LinearMipmapLinearFilter;
  texture.magFilter = THREE.LinearFilter;

  // Material – basic node material with the texture map
  const material = new THREE.MeshBasicNodeMaterial({ map: texture });

  // Mesh creation
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(config.position.x, config.position.y, config.position.z);
  mesh.rotation.set(
    config.rotation.x,
    config.rotation.y,
    config.rotation.z
  );
  mesh.scale.set(config.scale.x, config.scale.y, config.scale.z);

  // Apply cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(mesh, primitive.params);
      }
    }
  }

  // Hover lift animation (rise‑in) – subtle 0.15 scene units
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    mesh.position,
    {
      y: mesh.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );

  // Event handlers attached to userData
  mesh.userData.handlers = {
    /**
     * Called when pointer enters the object.
     */
    hoverEnter: () => {
      hoverTimeline.play();
    },

    /**
     * Called when pointer leaves the object.
     */
    hoverLeave: () => {
      hoverTimeline.reverse();
    },

    /**
     * Called on click – emits navigation event.
     */
    click: () => {
      if (ctx.emit && typeof ctx.emit === 'function') {
        ctx.emit('hub-pricing.select');
      }
    },
  };

  // Cleanup routine
  mesh.userData.cleanup = () => {
    hoverTimeline.kill();
    geometry.dispose();
    material.dispose();
    if (texture) {
      texture.dispose();
    }
    // Remove handlers reference
    delete mesh.userData.handlers;
    delete mesh.userData.cleanup;
  };

  return mesh;
}
